import re
from datetime import datetime
from typing import Tuple, Dict, Any

def validate_id_card_cn(id_card: str) -> Tuple[bool, str, Dict[str, Any]]:
    """
    验证中国大陆身份证号码。
    """
    if not id_card:
        return False, 'invalid', {}

    id_card = str(id_card).strip().upper()

    # 基本格式检查
    if len(id_card) == 15:
        pattern = r'^[1-9]\d{14}$'
        if not re.match(pattern, id_card):
            return False, 'invalid', {}
        return True, '15位', _parse_15(id_card)

    elif len(id_card) == 18:
        pattern = r'^[1-9]\d{16}[\dX]$'
        if not re.match(pattern, id_card):
            return False, 'invalid', {}

        # 校验码验证
        if not _check_18_digit(id_card):
            return False, 'invalid', {}

        return True, '18位', _parse_18(id_card)

    return False, 'invalid', {}

def _check_18_digit(id_card: str) -> bool:
    """验证18位身份证校验码"""
    weights = [7, 9, 10, 5, 8, 4, 2, 1, 6, 3, 7, 9, 10, 5, 8, 4, 2]
    check_codes = '10X98765432'

    sum_val = sum(int(id_card[i]) * weights[i] for i in range(17))
    return check_codes[sum_val % 11] == id_card[17]

def _parse_15(id_card: str) -> Dict:
    """解析15位身份证"""
    province_code = id_card[:2]
    year = '19' + id_card[6:8]
    month = id_card[8:10]
    day = id_card[10:12]
    gender_code = int(id_card[14])

    return {
        'province': _get_province(province_code),
        'birth_date': f'{year}-{month}-{day}',
        'gender': '男' if gender_code % 2 == 1 else '女'
    }

def _parse_18(id_card: str) -> Dict:
    """解析18位身份证"""
    province_code = id_card[:2]
    year = id_card[6:10]
    month = id_card[10:12]
    day = id_card[12:14]
    gender_code = int(id_card[16])

    return {
        'province': _get_province(province_code),
        'birth_date': f'{year}-{month}-{day}',
        'gender': '男' if gender_code % 2 == 1 else '女'
    }

def _get_province(code: str) -> str:
    """根据代码获取省份"""
    provinces = {
        '11': '北京', '12': '天津', '13': '河北', '14': '山西', '15': '内蒙古',
        '21': '辽宁', '22': '吉林', '23': '黑龙江',
        '31': '上海', '32': '江苏', '33': '浙江', '34': '安徽', '35': '福建',
        '36': '江西', '37': '山东',
        '41': '河南', '42': '湖北', '43': '湖南', '44': '广东', '45': '广西',
        '46': '海南',
        '50': '重庆', '51': '四川', '52': '贵州', '53': '云南', '54': '西藏',
        '61': '陕西', '62': '甘肃', '63': '青海', '64': '宁夏', '65': '新疆'
    }
    return provinces.get(code, '未知')
